args.sparql:
SELECT ?father ?fatherLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Helena_of_Nassau dbp:father ?father .
  OPTIONAL {
    { ?father dbo:birthPlace ?birthPlace } UNION { ?father dbp:birthPlace ?birthPlace }
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER (lang(?fatherLabel) = "en") }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER (lang(?birthPlaceLabel) = "en") }
}

SELECT ?s ?father WHERE {
  ?s rdfs:label "Helena of Nassau"@en .
  ?s dbp:father ?father .
}

SELECT ?s ?label ?father WHERE {
  ?s rdfs:label ?label .
  FILTER(lang(?label) = "en")
  FILTER(CONTAINS(LCASE(STR(?label)), "helena"))
  ?s dbp:father ?father .
} LIMIT 50

SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
  { <http://dbpedia.org/resource/William,_Duke_of_Nassau> dbo:birthPlace ?birthPlace }
  UNION
  { <http://dbpedia.org/resource/William,_Duke_of_Nassau> dbp:birthPlace ?birthPlace }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = "en") }
}

SELECT DISTINCT ?birthPlace ?birthPlaceLabel WHERE {
  ?hel rdfs:label "Princess Helena of Nassau"@en .
  ?hel dbp:father ?father .
  { ?father dbo:birthPlace ?birthPlace } UNION { ?father dbp:birthPlace ?birthPlace } .
  FILTER NOT EXISTS { ?birthPlace a dbo:House }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = "en") }
}

